fn compute_arith_sum(n: u64) -> u64 {
    let mut sum: u64 = 0;
    let mut idx: u64 = 0;

    // Loop to compute the sum of the first n natural numbers
    while idx < n {
        idx += 1;
        sum += idx;

        // Ensure that the sum remains less than 10,000
        if sum >= 10_000 {
            break; // This should not happen due to the assumption, but we safeguard it
        }
    }

    sum
}

